export function openFeedback(){const existing=document.querySelector('.feedback-page');if(existing){existing.showModal();return}const d=document.createElement('dialog');d.className='feedback-page';d.innerHTML=`<header><h2>Feedback</h2><button type="button" id="close-feedback" aria-label="Close feedback">×</button></header><form><label>What would you like to send?<select name="type"><option value="bug">Report a bug</option><option value="feature">Suggest a feature</option></select></label><label>Title<input name="title" required minlength="3" maxlength="120" placeholder="A short description"></label><label>Details<textarea name="details" required minlength="10" maxlength="8000" placeholder="What happened? What did you expect? For a feature, describe what you would like to create."></textarea></label><label>Email for a reply <span>(optional)</span><input name="email" type="email" maxlength="200" autocomplete="email"></label><p>Your project files are not included in this report.</p><div role="status" id="feedback-status"></div><footer><button type="button" id="feedback-cancel">Cancel</button><button type="submit" class="primary">Send feedback</button></footer></form>`;document.body.append(d);const close=()=>d.close();d.querySelector('#close-feedback').onclick=d.querySelector('#feedback-cancel').onclick=close;d.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=d.querySelector('[type=submit]'),status=d.querySelector('#feedback-status');button.disabled=true;button.textContent='Sending…';status.textContent='';try{const values=Object.fromEntries(new FormData(e.target));const base=location.hostname==='127.0.0.1'&&location.port==='14327'?'https://playform-studio-production.up.railway.app':'';const response=await fetch(base+'/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)}),result=await response.json();if(!response.ok)throw Error(result.error||'Could not send feedback.');status.textContent='Received. Your reference is '+result.id;d.querySelector('form').reset();button.textContent='Send another report'}catch(error){status.textContent=error.message;button.textContent='Try again'}finally{button.disabled=false}};d.onclose=()=>d.remove();d.showModal()}
